;
; font.s - 5x7 bitmap font for the HIRES screens (generated by
; tools/mkfont.py).  One glyph is seven bytes, one per row, each
; row shifted into the six pixel cell the way the screen wants it:
; bit 5 is the leftmost pixel and bit 0 is the gap column.  Laying
; the table out like this costs a byte a row over the old packed
; form, and saves the blitter two shifts and a mask per row.
;
        .export         _font6

        .rodata
_font6:
        .byte   $00, $00, $00, $00, $00, $00, $00        ; ' '
        .byte   $08, $08, $08, $08, $08, $00, $08        ; '!'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '"'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '#'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '$'
        .byte   $32, $34, $04, $08, $10, $16, $26        ; '%'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '&'
        .byte   $08, $08, $00, $00, $00, $00, $00        ; '''
        .byte   $04, $08, $10, $10, $10, $08, $04        ; '('
        .byte   $10, $08, $04, $04, $04, $08, $10        ; ')'
        .byte   $00, $2A, $1C, $3E, $1C, $2A, $00        ; '*'
        .byte   $00, $08, $08, $3E, $08, $08, $00        ; '+'
        .byte   $00, $00, $00, $00, $00, $08, $10        ; ','
        .byte   $00, $00, $00, $1C, $00, $00, $00        ; '-'
        .byte   $00, $00, $00, $00, $00, $00, $08        ; '.'
        .byte   $02, $02, $04, $08, $10, $20, $20        ; '/'
        .byte   $1C, $22, $26, $2A, $32, $22, $1C        ; '0'
        .byte   $08, $18, $08, $08, $08, $08, $1C        ; '1'
        .byte   $1C, $22, $02, $04, $08, $10, $3E        ; '2'
        .byte   $3C, $02, $02, $1C, $02, $02, $3C        ; '3'
        .byte   $04, $0C, $14, $24, $3E, $04, $04        ; '4'
        .byte   $3E, $20, $3C, $02, $02, $22, $1C        ; '5'
        .byte   $0C, $10, $20, $3C, $22, $22, $1C        ; '6'
        .byte   $3E, $02, $04, $08, $10, $10, $10        ; '7'
        .byte   $1C, $22, $22, $1C, $22, $22, $1C        ; '8'
        .byte   $1C, $22, $22, $1E, $02, $04, $18        ; '9'
        .byte   $00, $08, $00, $00, $00, $08, $00        ; ':'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; ';'
        .byte   $02, $04, $08, $10, $08, $04, $02        ; '<'
        .byte   $00, $00, $3E, $00, $3E, $00, $00        ; '='
        .byte   $20, $10, $08, $04, $08, $10, $20        ; '>'
        .byte   $1C, $22, $02, $04, $08, $00, $08        ; '?'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '@'
        .byte   $1C, $22, $22, $3E, $22, $22, $22        ; 'A'
        .byte   $3C, $22, $22, $3C, $22, $22, $3C        ; 'B'
        .byte   $1E, $20, $20, $20, $20, $20, $1E        ; 'C'
        .byte   $3C, $22, $22, $22, $22, $22, $3C        ; 'D'
        .byte   $3E, $20, $20, $3C, $20, $20, $3E        ; 'E'
        .byte   $3E, $20, $20, $3C, $20, $20, $20        ; 'F'
        .byte   $1C, $22, $20, $2E, $22, $22, $1C        ; 'G'
        .byte   $22, $22, $22, $3E, $22, $22, $22        ; 'H'
        .byte   $3E, $08, $08, $08, $08, $08, $3E        ; 'I'
        .byte   $0E, $04, $04, $04, $04, $24, $18        ; 'J'
        .byte   $22, $24, $28, $30, $28, $24, $22        ; 'K'
        .byte   $20, $20, $20, $20, $20, $20, $3E        ; 'L'
        .byte   $22, $36, $2A, $22, $22, $22, $22        ; 'M'
        .byte   $22, $32, $2A, $26, $22, $22, $22        ; 'N'
        .byte   $1C, $22, $22, $22, $22, $22, $1C        ; 'O'
        .byte   $3C, $22, $22, $3C, $20, $20, $20        ; 'P'
        .byte   $1C, $22, $22, $22, $2A, $24, $1A        ; 'Q'
        .byte   $3C, $22, $22, $3C, $28, $24, $22        ; 'R'
        .byte   $1E, $20, $20, $1C, $02, $02, $3C        ; 'S'
        .byte   $3E, $08, $08, $08, $08, $08, $08        ; 'T'
        .byte   $22, $22, $22, $22, $22, $22, $1C        ; 'U'
        .byte   $22, $22, $22, $22, $22, $14, $08        ; 'V'
        .byte   $22, $22, $22, $2A, $2A, $36, $22        ; 'W'
        .byte   $22, $22, $14, $08, $14, $22, $22        ; 'X'
        .byte   $22, $22, $14, $08, $08, $08, $08        ; 'Y'
        .byte   $3E, $02, $04, $08, $10, $20, $3E        ; 'Z'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '['
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '\'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; ']'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '^'
        .byte   $00, $00, $00, $00, $00, $00, $00        ; '_'

        .export         _xmask, _mfrom, _mto
_xmask:                 ; bit for pixel x%6, leftmost first
        .byte   $20, $10, $08, $04, $02, $01
_mfrom:                 ; bits from x%6 down to the byte edge
        .byte   $3F, $1F, $0F, $07, $03, $01
_mto:                   ; bits from the byte edge to x%6
        .byte   $20, $30, $38, $3C, $3E, $3F
